    "Europe/Kiev": "Europe/Kyiv", "America/Buenos_Aires": "America/Argentina/Buenos_Aires",
    "Brazil/East": "America/Sao_Paulo", "UTC": "Etc/UTC", "GMT": "Etc/UTC",
}
_ZONE_FILES = ("/usr/share/zoneinfo/tzdata.zi", "/usr/share/zoneinfo/tzdata.zi")


def _tz(tz: str) -> str:
    tz = tz.strip()
    m = re.fullmatch(r"(?:UTC|GMT)?\\s*([+-])(\\d{1,2})(?::?(\\d{2}))?", tz)
    if m:
        hours = int(m.group(2))
        if m.group(3) not in (None, "00"):
            raise ValueError(f"unsupported fractional offset {tz}")
        if hours == 0:
            return "Etc/UTC"
        return f"Etc/GMT{'+' if m.group(1) == '-' else '-'}{hours}"
    if tz in _LINKS:
        return _LINKS[tz]
    for path in _ZONE_FILES[:1]:
        try:
            with open(path) as f:
                for row in f:
                    parts = row.split()
                    if len(parts) == 3 and parts[0] == "L" and parts[2] == tz and "/" in parts[1]:
                        return parts[1]
        except OSError:
            pass
    return tz


_LOCALES = ("en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP")


def _locale(raw: str) -> str:
    tag = re.split(r"[.@]", raw.strip())[0].replace("_", "-")
    for cand in _LOCALES:
        if cand.lower() == tag.lower():
            return cand
    lang = tag.split("-")[0].lower()
    return lang if lang in _LOCALES else "en-US"


_DIGITS0 = {"CLP", "ISK", "JPY", "KRW", "UGX", "VND"}
_DIGITS3 = {"BHD", "JOD", "KWD", "OMR", "TND"}

# locale: (decimal, group, code after)
_STYLE = {
    "en-US": (".", ",", False), "en-GB": (".", ",", False), "ja-JP": (".", ",", False),
    "en-IN": (".", ",", False), "pt-BR": (",", ".", False), "de-DE": (",", ".", True),
    "es": (",", ".", True), "de-CH": (".", "\\u2019", True), "fr-FR": (",", "\\u202f", True),
}


def _digits(currency: str) -> int:
    return 0 if currency in _DIGITS0 else 3 if currency in _DIGITS3 else 2


def _round(value: str, digits: int) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_EVEN)


def _group(integer: str, locale: str, sep: str) -> str:
    if locale == "es" and len(integer) == 4:
        return integer
    if locale == "en-IN" and len(integer) > 3:
        head, tail = integer[:-3], integer[-3:]
        groups = []
        while head:
            groups.insert(0, head[-2:])
            head = head[:-2]
        return sep.join(groups + [tail])
    groups = []
    while integer:
        groups.insert(0, integer[-3:])
        integer = integer[:-3]
    return sep.join(groups)


def _text(value: Decimal, currency: str, locale: str) -> str:
    dec, grp, after = _STYLE[locale]
    digits = _digits(currency)
    sign = "-" if value < 0 else ""
    fixed = f"{abs(value):.{digits}f}"
    integer, _, frac = fixed.partition(".")
    number = sign + _group(integer, locale, grp) + (dec + frac if digits else "")
    return f"{number}\\u00a0{currency}" if after else f"{currency}\\u00a0{number}"


def monthly_statement(transport: Transport, merchant: Merchant, year: int, month: int) -> Statement:
    """The statement of `merchant` for one calendar month, with its days in the merchant's time zone.

    One line per day that has settlements, in day order, with the figures and the text the
    Meridale dashboard shows. Raises ApiError when the API answers with an error.
    """
    first = date(year, month, 1)
    end = date(year + month // 12, month % 12 + 1, 1)
    locale = _locale(merchant.locale)
    params = {
        "merchant_id": merchant.id,
        "tz": _tz(merchant.tz),
        "from": first.isoformat(),
        "to": end.isoformat(),
        "locale": locale,
    }
    report = _call(transport, "GET", f"{BASE}/settlements", params)
    currency = report["currency"]
    digits = _digits(currency)
    lines = []
    for d in report["days"]:
        gross, fees, refunds = (_round(d[k], digits) for k in ("gross", "fees", "refunds"))
        net = gross - fees - refunds
        lines.append(Line(date.fromisoformat(d["day"]), gross, fees, refunds, net, _text(net, currency, locale)))
    total = sum((line.net for line in lines), Decimal(0)).quantize(Decimal(1).scaleb(-digits))
    return Statement(merchant.id, currency, tuple(lines), total, _text(total, currency, locale))
'''
